   678      if (cinfo->Ah == 0) {
   679        if (cinfo->Ss == 0)
   680          entropy->pub.decode_mcu = decode_mcu_DC_first;
   681        else
   682          entropy->pub.decode_mcu = decode_mcu_AC_first;
   683      } else {
   684        if (cinfo->Ss == 0)
   685          entropy->pub.decode_mcu = decode_mcu_DC_refine;
   686        else
   687          entropy->pub.decode_mcu = decode_mcu_AC_refine;
   688      }
   689    } else {
   690      /* Check that the scan parameters Ss, Se, Ah/Al are OK for sequential JPEG.
   691       * This ought to be an error condition, but we make it a warning.
   692       */
   693      if (cinfo->Ss != 0 || cinfo->Se != DCTSIZE2 - 1 ||
   694          cinfo->Ah != 0 || cinfo->Al != 0)
   695        WARNMS(cinfo, JWRN_NOT_SEQUENTIAL);
   696      /* Select MCU decoding routine */
   697      entropy->pub.decode_mcu = decode_mcu;
   698    }
   699
   700    /* Allocate & initialize requested statistics areas */
   701    for (ci = 0; ci < cinfo->comps_in_scan; ci++) {
   702      compptr = cinfo->cur_comp_info[ci];
   703      if (!cinfo->progressive_mode || (cinfo->Ss == 0 && cinfo->Ah == 0)) {
   704        tbl = compptr->dc_tbl_no;
   705        if (tbl < 0 || tbl >= NUM_ARITH_TBLS)
   706          ERREXIT1(cinfo, JERR_NO_ARITH_TABLE, tbl);
   707        if (entropy->dc_stats[tbl] == NULL)
   708          entropy->dc_stats[tbl] = (unsigned char *)(*cinfo->mem->alloc_small)
   709            ((j_common_ptr)cinfo, JPOOL_IMAGE, DC_STAT_BINS);
   710        MEMZERO(entropy->dc_stats[tbl], DC_STAT_BINS);
   711        /* Initialize DC predictions to 0 */
   712        entropy->last_dc_val[ci] = 0;
   713        entropy->dc_context[ci] = 0;
   714      }
   715      if (!cinfo->progressive_mode || cinfo->Ss) {
   716        tbl = compptr->ac_tbl_no;
   717        if (tbl < 0 || tbl >= NUM_ARITH_TBLS)
   718          ERREXIT1(cinfo, JERR_NO_ARITH_TABLE, tbl);
   719        if (entropy->ac_stats[tbl] == NULL)
   720          entropy->ac_stats[tbl] = (unsigned char *)(*cinfo->mem->alloc_small)
   721            ((j_common_ptr)cinfo, JPOOL_IMAGE, AC_STAT_BINS);
   722        MEMZERO(entropy->ac_stats[tbl], AC_STAT_BINS);
   723      }
   724    }
