   727    entropy->c = 0;
   728    entropy->a = 0;
   729    entropy->ct = -16;    /* force reading 2 initial bytes to fill C */
   730
   731    /* Initialize restart counter */
   732    entropy->restarts_to_go = cinfo->restart_interval;
   733  }
